script:
(function () {
  'use strict';
  // HELOC credit limit and payments across the draw and repayment periods.
  //   Credit line = home value * max combined LTV - mortgage balance (never below 0).
  //   Draw period: draws added at the start of the month (all in month 1, or equal monthly amounts);
  //   payment = interest on the balance (balance * rate / 12) + any extra principal.
  //   Repayment period: the balance left is amortized, P = B * i / (1 - (1 + i)^-n) (P = B / n at 0%).
  //   Rate sensitivity reruns the same plan with the rate 1, 2 and 3 points higher for the whole life.
  // Verified in Node (scratchpad tests/m5): $50,000 at 8% with a 5-yr draw and 15-yr repayment gives
  //   $333.33 interest-only and $477.83 repayment payments (closed form; same as a published
  //   calculator's defaults); credit line $600,000 x 80% - $250,000 = $230,000; even draws of
  //   $50,000 over 120 months peak at the full-balance interest payment; balance ends at exactly 0;
  //   0% rate gives zero interest; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function paymentFor(balance, i, n) {
    if (n <= 0 || balance <= 0) return 0;
    if (i === 0) return balance / n;
    return balance * i / (1 - Math.pow(1 + i, -n));
  }

  function simulate(o) {
    var i = o.rate / 12, bal = 0, months = [], interest = 0, peakDraw = 0, lastDraw = 0, firstDraw = 0;
    for (var m = 1; m <= o.drawMonths; m++) {
      var draw = o.even ? o.amount / o.drawMonths : (m === 1 ? o.amount : 0);
      bal += draw;
      var intr = bal * i;
      var extra = Math.min(o.extra, bal);
      bal -= extra;
      if (bal < 0.005) bal = 0;
      var pay = intr + extra;
      interest += intr;
      if (m === 1) firstDraw = pay;
      peakDraw = Math.max(peakDraw, pay);
      lastDraw = pay;
      months.push({ phase: 'Draw', draw: draw, pay: pay, interest: intr, balance: bal });
    }
    var endOfDraw = bal, repay = paymentFor(bal, i, o.repayMonths);
    for (var k = 1; k <= o.repayMonths && bal > 0.005; k++) {
      var int2 = bal * i;
      var principal = k === o.repayMonths ? bal : Math.min(repay - int2, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      interest += int2;
      months.push({ phase: 'Repay', draw: 0, pay: principal + int2, interest: int2, balance: bal });
    }
    return { months: months, interest: interest, firstDraw: firstDraw, peakDraw: peakDraw, lastDraw: lastDraw,
             repay: repay, endOfDraw: endOfDraw };
  }

  function clearResults() {
    ['heLine', 'heIO', 'heRepay', 'heShock', 'heEquity', 'heCltvAfter', 'heEndBalance', 'heTotalInterest',
     'heFees', 'heTotalCost', 'heIONote'].forEach(function (id) { setText(id, '–'); });
    el('heWarn').hidden = true;
    el('heRates').innerHTML = '';
    el('heYears').innerHTML = '';
  }

  function update() {
    var value = read('heValue'), owed = read('heMortgage', true), cltv = read('heCltv'),
        amount = read('heAmount'), rate = read('heRate'), drawY = read('heDrawYears'), repayY = read('heRepayYears'),
        even = el('hePattern').value === 'even', extra = read('heExtra', true),
        closing = read('heClosing', true), annualFee = read('heAnnualFee', true);
    var error = el('heError'), msg = '';
    if (isNaN(value) || value <= 0) msg = 'Enter your home’s current value.';
    else if (isNaN(owed) || owed < 0) msg = 'The mortgage balance cannot be negative.';
    else if (isNaN(cltv) || cltv <= 0 || cltv > 100) msg = 'Enter a combined loan-to-value limit from 1% to 100%.';
    else if (isNaN(amount) || amount <= 0) msg = 'Enter the amount you plan to borrow.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(drawY) || drawY < 1 || drawY > 30 || drawY % 1 !== 0) msg = 'Enter a draw period of 1 to 30 whole years.';
    else if (isNaN(repayY) || repayY < 1 || repayY > 30 || repayY % 1 !== 0) msg = 'Enter a repayment period of 1 to 30 whole years.';
    else if ([extra, closing, annualFee].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Extra payments and fees cannot be negative.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var line = Math.max(0, value * cltv / 100 - owed);
    var opts = { amount: amount, rate: rate / 100, drawMonths: drawY * 12, repayMonths: repayY * 12, even: even, extra: extra };
    var r = simulate(opts);
    var fees = closing + annualFee * drawY;
    var shock = r.repay - r.lastDraw;

    setText('heLine', money0.format(line));
    setText('heIO', money.format(r.peakDraw));
    setText('heRepay', money.format(r.repay));
    setText('heShock', r.lastDraw > 0 ? (shock >= 0 ? '+' : '−') + money.format(Math.abs(shock)) + ' (' + (shock >= 0 ? '+' : '−') + Math.abs(shock / r.lastDraw * 100).toFixed(0) + '%)' : '+' + money.format(Math.max(0, shock)));
    setText('heEquity', money0.format(Math.max(0, value - owed)));
    setText('heCltvAfter', ((owed + amount) / value * 100).toFixed(1) + '%');
    setText('heEndBalance', money.format(r.endOfDraw));
    setText('heTotalInterest', money.format(r.interest));
    setText('heFees', money.format(fees));
    setText('heTotalCost', money.format(r.interest + fees));
    setText('heIONote', even
      ? 'Draw-period payments rise from ' + money.format(r.firstDraw) + ' to ' + money.format(r.peakDraw) + ' as you draw more of the line.'
      : 'You pay interest on the full amount from the first month' + (extra > 0 ? ', plus your extra principal.' : '.'));

    var warn = el('heWarn');
    if (line <= 0) { warn.hidden = false; setText('heWarnText', 'With a ' + cltv + '% limit, your mortgage already uses all the equity a lender would count, so you would likely not qualify for a line of credit.'); }
    else if (amount > line) { warn.hidden = false; setText('heWarnText', 'You plan to borrow ' + money0.format(amount) + ', more than the estimated line of ' + money0.format(line) + '. The payments below still show the full amount.'); }
    else warn.hidden = true;

    el('heRates').innerHTML = [0, 1, 2, 3].map(function (d) {
      var s = d === 0 ? r : simulate({ amount: amount, rate: rate / 100 + d / 100, drawMonths: opts.drawMonths, repayMonths: opts.repayMonths, even: even, extra: extra });
      return '<tr><th scope="row">' + (rate + d).toFixed(2).replace(/\.?0+$/, '') + '%' + (d ? ' (+' + d + ')' : ' (today)') + '</th><td>' + money.format(s.peakDraw) +
        '</td><td>' + money.format(s.repay) + '</td><td>' + money.format(s.interest) + '</td></tr>';
    }).join('');

    var html = [], drawn = 0, paid = 0, intr = 0;
    r.months.forEach(function (row, idx) {
      drawn += row.draw; paid += row.pay; intr += row.interest;
      if ((idx + 1) % 12 === 0 || idx === r.months.length - 1) {
        var year = Math.ceil((idx + 1) / 12);
        html.push('<tr><td>' + year + '</td><td>' + (year <= drawY ? 'Draw' : 'Repayment') + '</td><td>' + money.format(drawn) +
          '</td><td>' + money.format(paid) + '</td><td>' + money.format(intr) + '</td><td>' + money.format(row.balance) + '</td></tr>');
        drawn = 0; paid = 0; intr = 0;
      }
    });
    el('heYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('heForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
